    "descriptionEn": "Your Oasis in Cambodia: Private Pool House Retreat! - Experience the perfect fusion of tradition and modernity in our traditional Cambodian wooden house. - 4 beautiful bedrooms, including 3 with en-suite bathrooms and 1 with a shared bathroom, offer both comfort and style. - Upstairs, a cozy living room complete with a sofa bed, a TV corner, and a workspace awaits. - Relax on the small terrace featuring a hanging chair that overlooks the water garden—a true reading haven! Fully Equipped Kitchen Downstairs, indulge your culinary desires in a fully equipped kitchen or fire up the backyard barbecue. Prepare and enjoy your own meals, or request to be served by our dedicated staff. Lush Water Garden Immerse yourself in our natural swimming pool, surrounded by a lush water garden. Thanks to tropical aquatic plants, the pool is completely free from harsh chemicals. Relaxation Spaces An extra-large canopy bed by the pool provides shade and privacy—perfect for enjoying a traditional Khmer massage. Nearby, a small wooden structure in the water garden offers a refreshing spot for cold drinks or a tranquil setting for tea at sunset. Every detail blends modern comfort with traditional charm, promising a rejuvenating escape for our guests. Special Offers & Complimentary Benefits - Airport Transfer: To ensure a smooth arrival, enjoy 30% OFF your airport pickup for just $35 per way. (Please note that airport drop-off for departure is available at our standard rate of $50). - Dining Voucher: As a thank-you for choosing to stay with us, every booking includes a complimentary gift voucher for Fellini Restaurant! Fellini Restaurant Voucher Details - Value: Up to $40 OFF your total dining bill. - Where to Use: Fellini Restaurant (Dine-in only). - How to Redeem: Simply present your voucher to your server when settling your bill. We look forward to welcoming you and hope you enjoy these exclusive benefits during your stay!",
