    "descriptionEn": "Located on Sivutha Boulevard in central Siem Reap, the Mekong Angkor Places Hotel is a popular mid-range Hotel known for its convenient location and traditional Khmer-style warm hospitality. It serves as a peaceful base for travellers visiting the world-famous Angkor Wat temple complex and exploring the vibrant city centre. * Prime Location: Situated within a 10-to-15 minute walk to Pub Street, the Night Market, Old Market and Lucky Mall. *Proximity to Angkor Wat: just s short 10-15minute drive (approx.8 km / 5miles) to the entrance of the Angkor Archaeological Park. * Outdoor Swimming Poll: Features a sun lounger area set amid tropical greenery a great spot to cool off after a hot day of temple exploration. *Dining: An on-site restaurant serving local Cambodian dishes as well as international breakfast buffets. * Spacious Rooms: Air-conditioned rooms featuring private balcony, flat-screen TVs, tea/coffee makers, mini-bars, and ensuite bathrooms. * Room types Available: -Superior / Deluxe rooms -Superior / Deluxe Tween rooms -Triple rooms & Family suites (ideal for small groups or families)",
