    "descriptionEn": "Wat Damnak House: Private Tropical Oasis Traditional Khmer Villa | Natural Pool Situated behind Wat Damnak Pagoda. Within walking distance of Pub Street and a 20-minute tuk-tuk ride to Angkor Wat. This charming wooden villa offers a unique blend of traditional Khmer style and modern comfort, surrounded by a lush tropical water garden. 4 beautiful rooms with en-suite bathrooms and 2 additional bedrooms with shared bathrooms, offering a total capacity for up to 12 guests. Start your morning with a relaxing cup of coffee or tea on our secluded terrace overlooking the lush garden, unwind with an in-house massage, or stay productive in the laptop-friendly workspace. The villa also features cozy reading areas, a dining lounge, a fully equipped kitchen, and an outdoor barbecue area. Cool off in our natural swimming pool, surrounded by a lush tropical garden. It’s completely chemical-free for a pure, clean swim. Special Offers & Complimentary Benefits - Airport Transfer: To ensure a smooth arrival, enjoy 30% OFF your airport pickup for just $35 per way. (Please note: Airport drop-off for departure is available at our standard rate of $50). - Dining Voucher: As a thank-you for staying with us, every booking includes a complimentary voucher for Fellini Restaurant! Fellini Restaurant Voucher Details - Value: Up to $40 OFF your total dining bill. - Where to Use: Fellini Restaurant (Dine-in only). - How to Redeem: Simply present your voucher to your server when settling your bill. We look forward to welcoming you and hope you enjoy these exclusive benefits during your stay!",
