    "categoryEn": "Hotel & Stay",
    "descriptionKh": "សណ្ឋាគារ ដឹ ហ្វាយ សេនស៍ ប៊ូទិក (The Five Senses Boutique Hotel) មានទីតាំងនៅ House NA, Street Riverside, East Street, Wat Damnak Village, Sangkat Sala Kamroeuk, Siem Reap Province, ខេត្តសៀមរាប។ តម្លៃស្នាក់នៅចាប់ពី $20+ ក្នុង ១ យប់។ មានបន្ទប់ស្អាត ផាសុកភាព និងអាចមើលរូបភាពបន្ទប់ពិតៗព្រមទាំងកក់ផ្ទាល់តាមរយៈ KhmerRooms។",
    "descriptionEn": "Nestled in the vibrant heart of Siem Reap, The Five Senses Boutique Hotel offers a unique and comfortable retreat for travelers seeking both relaxation and adventure. The hotel beautifully combines traditional Khmer architecture with modern amenities, creating an inviting atmosphere rich in local culture. Guests can indulge their senses with spacious, elegantly designed rooms featuring warm colors and natural materials. Each room is equipped with modern conveniences, including complimentary Wi-Fi, air conditioning, and flat-screen TVs, ensuring a comfortable stay. Many rooms also offer stunning views of the swimming pool. The hotel’s on-site restaurant serves a breakfast of Cambodian and international cuisines, highlighting fresh, locally sourced ingredients. Guests can savor their meals while enjoying the serene surroundings. The bar offers a selection of refreshing cocktails and local beverages, perfect for unwinding after a day of exploration. The hotel also offers guided tours and excursions to nearby attractions such as the famous Angkor Wat temple complex, ensuring guests experience the rich heritage of the region. With its welcoming ambiance, attentive staff, and prime location, The Five Senses Boutique Hotel is the perfect choice for travelers wanting to immerse themselves in the beauty and culture of Siem Reap.",
