    "descriptionEn": "Welcome to Archaic House Siem Reap, your ideal choice for budget-friendly accommodation in the heart of Siem Reap, Cambodia. Perfectly located just a short walk from the vibrant Pub Street, bustling Old Market, and scenic Siem Reap River, Archaic House puts the best of the city right at your doorstep. Whether you’re a solo traveler, couple, or family, Archaic House offers comfortable and affordable rooms with adequate amenities, including air conditioning, cozy beds, private bathrooms with complimentary toiletries, free Wi-Fi, and fresh linens. Our central location makes it easy to explore famous attractions such as Angkor Wat, Angkor National Museum, and Wat Thmei, while nearby cultural landmarks like Artisans D’Angkor and the Royal Residence are also just minutes away. Guests can enjoy free private parking, an optional airport shuttle at charge, laundry and ironing services, and business-friendly facilities for convenience. At Archaic House Siem Reap, we combine great value, attentive service, and a prime location near Pub Street, Old Market, and Siem Reap River to ensure every guest has a memorable stay. Whether you’re visiting for sightseeing, local cuisine, or exploring the city’s nightlife, Archaic House is your smart choice for affordable, centrally located accommodation in Siem Reap.",
