    "descriptionEn": "Experience the charm of Siem Reap in our 5-bedroom traditional Khmer villa. Located in the vibrant Wat Bo area with easy access to top attractions, it is perfect for families or groups seeking a cultural immersion in Cambodia. The ground floor boasts 2 air-conditioned bedrooms (3 beds, sleeps 4), each featuring a full private bathroom. You will also find a fully equipped kitchen with a half bathroom, and a spacious sofa in the living room for additional sleeping space. Upstairs, find tranquility on the terrace or relax in one of the 3 air-conditioned bedrooms (sleeps 6), each complete with an ensuite full bathroom. Outdoor space, enjoy our organic swimming pool, relax on the cushioned patio, or unwind in the hammock. Experience authentic Cambodian living with modern comforts. Special Offers & Complimentary Benefits - Airport Transfer: To ensure a smooth arrival, enjoy 30% OFF your airport pickup for just $35 per way. (Please note that airport drop-off for departure is available at our standard rate of $50). - Dining Voucher: As a thank you for choosing to stay with us, every booking includes a complimentary gift voucher for Fellini Restaurant! Fellini Restaurant Voucher Details: - Value: Up to $40 OFF your total dining bill. - Where to Use: Fellini Restaurant (Dine-in only). - How to Redeem: Simply present your voucher to your server when settling your bill. We look forward to welcoming you and hope you enjoy these exclusive benefits during your stay!",
