    "descriptionKh": "សូលីតាំង ដំណាក់ វីឡា សៀមរាប (Solitaire Damnak Villa) មានទីតាំងនៅ Wat Damnak Road, Krong Siem Reap, ខេត្តសៀមរាប។ តម្លៃស្នាក់នៅចាប់ពី $40+ ក្នុង ១ យប់។ មានបន្ទប់ស្អាត ផាសុកភាព និងអាចមើលរូបភាពបន្ទប់ពិតៗព្រមទាំងកក់ផ្ទាល់តាមរយៈ KhmerRooms។",
    "descriptionEn": "Wake up to the tropical charm of Solitaire Damnak Villa Hotel, a romantic retreat where villa-style comfort meets the warmth of Cambodian hospitality. Perfect for couples and ideal for honeymooners, our boutique villa offers the perfect blend of intimacy, comfort, and elegance just minutes from Pub Street and the Old Market. Begin your mornings with serene garden views, a refreshing dip in the pool, and a delicious breakfast at our Baichan Restaurant. Spend lazy afternoons unwinding on your private balcony or sharing a cool drink in our tranquil tropical garden—a true hideaway for romance. After exploring the wonders of Angkor Wat or the vibrant streets of Siem Reap, return to your peaceful sanctuary designed for love and relaxation. Each suite blends modern amenities with authentic local style, featuring air conditioning, free WiFi, a mini-bar, and spacious living areas—everything you need for a cozy and romantic stay. Our dedicated team is always on hand to arrange couples’ tours, spa treatments, or romantic surprises, ensuring your stay is as effortless as it is unforgettable. Discover your romantic Siem Reap escape—a boutique villa retreat where relaxation, adventure, and love come together in the heart of Cambodia. Couples in particular like the location – they rated it 9.2 for a two-person trip",
