    "descriptionEn": "Baahu Villa- Siem Reap features parking garage for guests, a bar and shared lounge in Siem Reap. With free WiFi, this 3-star hotel has a garden and a terrace. The accommodation provides a 24-hour front desk, a concierge service and currency exchange for guests. The hotel will provide guests with air-conditioned rooms offering a desk, a kettle, a fridge, a minibar, a safety deposit box, a flat-screen TV and a private bathroom with a shower. At Baahu Villa- Siem Reap each room is equipped with bed linen and towels. We have contributed in a joint effort to reduce the single use plastic through offering the refillable container for most of hotel's amenities such as shampoo, shower gel, hand wash. Also, we avoid using the plastic and single use bottle of water provided in each room by replacing with the refillable glass bottles of water. Baahu Villa- Siem Reap set herself as part of contribution to underprivileged personnel aim to grow skill and experience in Hotel industry through job opportunities and training. Popular points of interest near the hotel include Pub Street, Old market, Pub-street and Major Cineplex Siem Reap. The nearest airport is Siem Reap Angkor International Airport (SAI), 50 km from Baahu Villa- Siem Reap.",
