    "categoryEn": "Hotel & Stay",
    "descriptionKh": "សណ្ឋាគារ គោព្រៃ សៀមរាប (Kouprey Hotel Siem Reap) មានទីតាំងនៅ Top Town Road, Krous Village, Svay Dangkum, Siem Reap, Cambodia, Top Town Road, Krous Village, Svay, ខេត្តសៀមរាប។ តម្លៃស្នាក់នៅចាប់ពី $25+ ក្នុង ១ យប់។ មានបន្ទប់ស្អាត ផាសុកភាព និងអាចមើលរូបភាពបន្ទប់ពិតៗព្រមទាំងកក់ផ្ទាល់តាមរយៈ KhmerRooms។",
    "descriptionEn": "Built in November 2014, Kouprey Hotel is a boutique hotel located in Siem Reap, Cambodia, the Kingdom of Wonder. At Kouprey Hotel we aim to make your stay in Siem Reap as enjoyable as possible by providing the highest level of service, spotlessly clean rooms and a safe environment. Kouprey provides the ultimate location for family, adventure and leisure travellers alike. We cater for a wide variety of needs and understand that each visitor is unique in how they experience the wonders of Siem Reap. We want all our guests to leave with good memories and feel embraced by the warm hospitality of Siem Reap. Kouprey Hotel is Cambodian owned and operated by local people who have inherent knowledge about Siem Reap and who abide by ethical and conservation principles to ensure benefits from the hotel are used to promote and preserve the cultural and natural heritage of Cambodia. This is very important to allow Cambodia to move forward from its recent traumatic past of the Pol Pot Period. Everyone has been affected and each of our staff has a story of what happened to them and their family. At the same time as the people suffered, the environment and many of our natural wildlife species, were also decimated, including Cambodia's national animal, the Kouprey. This beautiful majestic animal with its long and wide-reaching horns has now become the country's symbol of the perilous situation for Cambodia's natural heritage. Thus the hotel has aptly chosen the Kouprey as its name to symbolize our vision to support Cambodia in creating ethical and environmentally sustainable solutions to secure our future.",
